const { test, before, after } = require('node:test')
const assert = require('node:assert/strict')
const { mkdtempSync, writeFileSync, rmSync } = require('node:fs')
const { join } = require('node:path')
const { spawnSync } = require('node:child_process')

let directory
let sample
let empty
let whitespace
before(() => {
  directory = mkdtempSync(join(__dirname, '.wordcount-test-'))
  sample = join(directory, 'sample.txt')
  empty = join(directory, 'empty.txt')
  whitespace = join(directory, 'whitespace.txt')
  writeFileSync(sample, 'hello world\nnext\n')
  writeFileSync(empty, '')
  writeFileSync(whitespace, ' one\ttwo\r\nthree\u2003four ')
})
after(() => rmSync(directory, { recursive: true, force: true }))

function run(...args) {
  const result = spawnSync(process.execPath, [join(__dirname, 'index.js'), ...args], { encoding: 'utf8' })
  assert.ifError(result.error)
  return result
}

for (const [flag, expected] of [['--lines', '3\n0\n2\n'], ['--words', '3\n0\n4\n']]) {
  test(`${flag} prints only the selected count for multiple files`, () => {
    const result = run(sample, flag, empty, whitespace)
    assert.equal(result.status, 0, result.stderr)
    assert.equal(result.stdout, expected)
    assert.equal(result.stderr, '')
  })

  test(`${flag} combines with --json`, () => {
    const result = run(flag, '--json', sample, empty)
    assert.equal(result.status, 0, result.stderr)
    const field = flag.slice(2)
    assert.deepEqual(JSON.parse(result.stdout), [
      { file: sample, [field]: 3 },
      { file: empty, [field]: 0 },
    ])
  })
}

test('default output preserves all counts and file names', () => {
  const result = run(sample, empty)
  assert.equal(result.status, 0, result.stderr)
  assert.equal(result.stdout, `3\t3\t17\t${sample}\n0\t0\t0\t${empty}\n`)
})

test('default JSON preserves all fields', () => {
  const result = run('--json', sample)
  assert.equal(result.status, 0, result.stderr)
  assert.deepEqual(JSON.parse(result.stdout), [
    { file: sample, lines: 3, words: 3, characters: 17 },
  ])
})

test('conflicting selectors report usage with exit code 2', () => {
  const result = run('--lines', sample, '--words')
  assert.equal(result.status, 2)
  assert.equal(result.stdout, '')
  assert.match(result.stderr, /usage:.*--lines.*--words/)
})

test('missing files report updated usage with exit code 2', () => {
  for (const args of [[], ['--json'], ['--lines'], ['--words'], ['--json', '--lines']]) {
    const result = run(...args)
    assert.equal(result.status, 2)
    assert.equal(result.stdout, '')
    assert.match(result.stderr, /usage:.*--lines.*--words/)
  }
})

